INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','participle-clauses','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"participle-clauses","title":"Participle clauses and reduced relatives","level":"C1","order":61,"summary":"Make related information more compact while keeping the implied subject and time relationship clear.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["An active -ing clause","A passive participle clause","A completed earlier action","Reduced relative clauses"],"rules":[{"title":"An active -ing clause","explanation":"A present-participle clause can add a reason, simultaneous activity or result. In an introductory clause, its understood subject normally matches the main-clause subject. Its form does not by itself set a present tense; the main clause and context provide time.","pattern":"**Walking home**, she called her brother.","commonMistakes":["Walking home, the rain began suggests that the rain was walking. This is a dangling modifier."],"examples":["Add an active participle clause: “**preparing** the visitor guide, the assistant noticed a mistake.”","Add an active participle clause: “**restoring** the old portrait, the assistant noticed a mistake.”"],"skill":"form"},{"title":"A passive participle clause","explanation":"A past-participle clause usually has a passive meaning: the implied subject receives the action. It can express a condition, reason or accompanying description. The main clause supplies the participant and time.","pattern":"**Kept cool**, the food lasts longer.","commonMistakes":["A past participle does not automatically mean past time; it often marks passive meaning."],"examples":["Make the earlier completion explicit: “Having **prepared** the visitor guide, we took a break.”","Make the earlier completion explicit: “Having **restored** the old portrait, we took a break.”"],"skill":"meaning"},{"title":"A completed earlier action","explanation":"Use **having + past participle** to make completion before the main action explicit. The passive equivalent is having been + participle. This is useful when sequence might otherwise be unclear, but long chains of participles can become hard to read.","pattern":"**Having checked** the map, we left.","commonMistakes":["Having checking is not the perfect-participle form: having takes a past participle."],"examples":["Reduce “who is doing the task”: “The assistant **preparing** the visitor guide is new.”","Reduce “who is doing the task”: “The assistant **restoring** the old portrait is new.”"],"skill":"contrast"},{"title":"Reduced relative clauses","explanation":"An -ing phrase after a noun can correspond to an active relative clause; a past-participle phrase can correspond to a passive relative. Keep the relation close to its noun and ensure that the reduction preserves the intended meaning.","pattern":"The person **waiting outside** is here. / The letter **sent yesterday** arrived.","commonMistakes":["Not every finite relative clause can be reduced without changing its meaning, tense or emphasis."],"examples":["In “Having prepared the visitor guide, the assistant left”, who performed the earlier action? → **the assistant**","In “Having restored the old portrait, the assistant left”, who performed the earlier action? → **the assistant**"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-participles"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"4bf82142-b627-5040-a69b-4dbf54cc8b38","topicSlug":"participle-clauses","level":"C1","prompt":"Add an active participle clause: “____ the visitor guide, the assistant noticed a mistake.”","choices":[{"id":"A","text":"To prepare"},{"id":"B","text":"prepares"},{"id":"C","text":"Has prepared"},{"id":"D","text":"preparing"}],"answerId":"D","hint":"The assistant performs both actions, so an **active -ing clause** can share that subject.","explanation":"**preparing the visitor guide** describes the assistant’s activity; the main subject supplies the understood actor.","keywords":["active-participle"],"skill":"active-participle","contextKey":"participle-clauses-1","fingerprint":"1ac3ea7bbdd5d5e8c090ecc76b1fc1f38d7435ce4c0f46957f85bf26ec723655","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-participles"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The assistant performs both actions, so an **active -ing clause** can share that subject.","**preparing the visitor guide** describes the assistant’s activity; the main subject supplies the understood actor.","Choose **preparing**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A to-infinitive would normally suggest purpose or a different relation, not the requested participle clause.","B":"A finite -s verb cannot open this subjectless participle clause.","C":"A finite perfect verb requires its own subject and is not this participle construction.","D":"**preparing the visitor guide** describes the assistant’s activity; the main subject supplies the understood actor."}}},{"id":"a403bd92-3005-569d-ae75-f1cb53826097","topicSlug":"participle-clauses","level":"C1","prompt":"Make the earlier completion explicit: “Having ____ the visitor guide, we took a break.”","choices":[{"id":"A","text":"to prepare"},{"id":"B","text":"been preparing"},{"id":"C","text":"prepared"},{"id":"D","text":"preparing"}],"answerId":"C","hint":"After **having**, choose the **past participle** for an earlier completed action.","explanation":"**Having prepared** marks the activity as completed before the break.","keywords":["perfect-participle"],"skill":"perfect-participle","contextKey":"participle-clauses-1","fingerprint":"9f2204bf027c9873df34c6b71afa0436575df75468315d2933119db6c97104de","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-participles"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["After **having**, choose the **past participle** for an earlier completed action.","**Having prepared** marks the activity as completed before the break.","Choose **prepared**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A to-infinitive does not follow having in a perfect participle clause.","B":"This would foreground earlier ongoing activity rather than the requested completed simple-perfect action.","C":"**Having prepared** marks the activity as completed before the break.","D":"Having requires a past participle for this perfect clause."}}},{"id":"81524d16-3cd5-517d-a4bf-0ea4ab695d46","topicSlug":"participle-clauses","level":"C1","prompt":"Reduce “who is doing the task”: “The assistant ____ the visitor guide is new.”","choices":[{"id":"A","text":"to prepare"},{"id":"B","text":"preparing"},{"id":"C","text":"prepares"},{"id":"D","text":"has prepared"}],"answerId":"B","hint":"The noun is the **actor**, and the action is in progress: use an **-ing modifier**.","explanation":"**preparing the visitor guide** is an active reduced relative modifying the assistant.","keywords":["reduced-active-relative"],"skill":"reduced-active-relative","contextKey":"participle-clauses-1","fingerprint":"93cae9fb754a4b764d1e01b7a7f344220a53a6eafde87a0498b149c10a983ed9","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-participles"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The noun is the **actor**, and the action is in progress: use an **-ing modifier**.","**preparing the visitor guide** is an active reduced relative modifying the assistant.","Choose **preparing**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"An infinitive suggests a task to be done rather than the stated ongoing activity.","B":"**preparing the visitor guide** is an active reduced relative modifying the assistant.","C":"A second finite verb here needs a relative pronoun or another clause structure.","D":"A finite perfect clause cannot follow the noun directly without a connector in this construction."}}},{"id":"bbcb3bad-8d8b-5673-a69b-4d8c84fc2221","topicSlug":"participle-clauses","level":"C1","prompt":"In “Having prepared the visitor guide, the assistant left”, who performed the earlier action?","choices":[{"id":"A","text":"the visitor guide"},{"id":"B","text":"an unnamed different person"},{"id":"C","text":"the sentence does not imply an actor"},{"id":"D","text":"the assistant"}],"answerId":"D","hint":"Link the opening participle clause to the **subject of the main clause**.","explanation":"The introductory participle clause normally shares its understood subject with **the assistant**, the main-clause subject.","keywords":["shared-participle-subject"],"skill":"shared-participle-subject","contextKey":"participle-clauses-1","fingerprint":"3f4de70211936fa80454131a53a439be835c5c27d78e0a1810e86f98ade631d5","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-participles"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Link the opening participle clause to the **subject of the main clause**.","The introductory participle clause normally shares its understood subject with **the assistant**, the main-clause subject.","Choose **the assistant**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"This is the object of the earlier action, not the actor.","B":"The structure normally links the implied actor to the main-clause subject.","C":"The main subject supplies the understood actor in this construction.","D":"The introductory participle clause normally shares its understood subject with **the assistant**, the main-clause subject."}}},{"id":"1fedf078-b925-59d8-a38b-b47107decfe8","topicSlug":"participle-clauses","level":"C1","prompt":"Add an active participle clause: “____ the old portrait, the assistant noticed a mistake.”","choices":[{"id":"A","text":"restoring"},{"id":"B","text":"To restore"},{"id":"C","text":"restores"},{"id":"D","text":"Has restored"}],"answerId":"A","hint":"The assistant performs both actions, so an **active -ing clause** can share that subject.","explanation":"**restoring the old portrait** describes the assistant’s activity; the main subject supplies the understood actor.","keywords":["active-participle"],"skill":"active-participle","contextKey":"participle-clauses-2","fingerprint":"abe6e2113855576f05de810dacc663d5f4a654ae3dde63a82429d5af3b237076","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-participles"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The assistant performs both actions, so an **active -ing clause** can share that subject.","**restoring the old portrait** describes the assistant’s activity; the main subject supplies the understood actor.","Choose **restoring**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"**restoring the old portrait** describes the assistant’s activity; the main subject supplies the understood actor.","B":"A to-infinitive would normally suggest purpose or a different relation, not the requested participle clause.","C":"A finite -s verb cannot open this subjectless participle clause.","D":"A finite perfect verb requires its own subject and is not this participle construction."}}},{"id":"0fe83a4e-d255-5b07-aa81-7bfff25c99fa","topicSlug":"participle-clauses","level":"C1","prompt":"Make the earlier completion explicit: “Having ____ the old portrait, we took a break.”","choices":[{"id":"A","text":"restoring"},{"id":"B","text":"to restore"},{"id":"C","text":"been restoring"},{"id":"D","text":"restored"}],"answerId":"D","hint":"After **having**, choose the **past participle** for an earlier completed action.","explanation":"**Having restored** marks the activity as completed before the break.","keywords":["perfect-participle"],"skill":"perfect-participle","contextKey":"participle-clauses-2","fingerprint":"68b109eae24cf88038956864fcc8f94f9b9adde863722a827ffe34ab67e7894d","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-participles"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["After **having**, choose the **past participle** for an earlier completed action.","**Having restored** marks the activity as completed before the break.","Choose **restored**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Having requires a past participle for this perfect clause.","B":"A to-infinitive does not follow having in a perfect participle clause.","C":"This would foreground earlier ongoing activity rather than the requested completed simple-perfect action.","D":"**Having restored** marks the activity as completed before the break."}}},{"id":"0c6cc4ef-fb5a-59bf-a6a2-d49f23b6250c","topicSlug":"participle-clauses","level":"C1","prompt":"Reduce “who is doing the task”: “The assistant ____ the old portrait is new.”","choices":[{"id":"A","text":"restores"},{"id":"B","text":"has restored"},{"id":"C","text":"to restore"},{"id":"D","text":"restoring"}],"answerId":"D","hint":"The noun is the **actor**, and the action is in progress: use an **-ing modifier**.","explanation":"**restoring the old portrait** is an active reduced relative modifying the assistant.","keywords":["reduced-active-relative"],"skill":"reduced-active-relative","contextKey":"participle-clauses-2","fingerprint":"1174810107c27ce3a4faa6717775e0fba34d2ca99bf296465144a007db942e64","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-participles"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The noun is the **actor**, and the action is in progress: use an **-ing modifier**.","**restoring the old portrait** is an active reduced relative modifying the assistant.","Choose **restoring**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A second finite verb here needs a relative pronoun or another clause structure.","B":"A finite perfect clause cannot follow the noun directly without a connector in this construction.","C":"An infinitive suggests a task to be done rather than the stated ongoing activity.","D":"**restoring the old portrait** is an active reduced relative modifying the assistant."}}},{"id":"43bae3bf-f463-5031-a379-0eb20ee675f6","topicSlug":"participle-clauses","level":"C1","prompt":"In “Having restored the old portrait, the assistant left”, who performed the earlier action?","choices":[{"id":"A","text":"an unnamed different person"},{"id":"B","text":"the sentence does not imply an actor"},{"id":"C","text":"the assistant"},{"id":"D","text":"the old portrait"}],"answerId":"C","hint":"Link the opening participle clause to the **subject of the main clause**.","explanation":"The introductory participle clause normally shares its understood subject with **the assistant**, the main-clause subject.","keywords":["shared-participle-subject"],"skill":"shared-participle-subject","contextKey":"participle-clauses-2","fingerprint":"d28d985040b4e262d843ab8d9c658e7858955360b36e0b4eaa4dab24bce3697f","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-participles"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Link the opening participle clause to the **subject of the main clause**.","The introductory participle clause normally shares its understood subject with **the assistant**, the main-clause subject.","Choose **the assistant**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The structure normally links the implied actor to the main-clause subject.","B":"The main subject supplies the understood actor in this construction.","C":"The introductory participle clause normally shares its understood subject with **the assistant**, the main-clause subject.","D":"This is the object of the earlier action, not the actor."}}},{"id":"c8cf2d03-6883-5461-a61d-557dbd78065a","topicSlug":"participle-clauses","level":"C1","prompt":"Add an active participle clause: “____ the garden fence, the assistant noticed a mistake.”","choices":[{"id":"A","text":"measuring"},{"id":"B","text":"To measure"},{"id":"C","text":"measures"},{"id":"D","text":"Has measured"}],"answerId":"A","hint":"The assistant performs both actions, so an **active -ing clause** can share that subject.","explanation":"**measuring the garden fence** describes the assistant’s activity; the main subject supplies the understood actor.","keywords":["active-participle"],"skill":"active-participle","contextKey":"participle-clauses-3","fingerprint":"4459f8cd328cb43fcdd6955fae4d0632e6fde62a62f06e691f1ed4163cb2c86b","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-participles"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The assistant performs both actions, so an **active -ing clause** can share that subject.","**measuring the garden fence** describes the assistant’s activity; the main subject supplies the understood actor.","Choose **measuring**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"**measuring the garden fence** describes the assistant’s activity; the main subject supplies the understood actor.","B":"A to-infinitive would normally suggest purpose or a different relation, not the requested participle clause.","C":"A finite -s verb cannot open this subjectless participle clause.","D":"A finite perfect verb requires its own subject and is not this participle construction."}}},{"id":"38de8c4a-2f92-50c3-aa4b-dd427c6f7627","topicSlug":"participle-clauses","level":"C1","prompt":"Make the earlier completion explicit: “Having ____ the garden fence, we took a break.”","choices":[{"id":"A","text":"to measure"},{"id":"B","text":"been measuring"},{"id":"C","text":"measured"},{"id":"D","text":"measuring"}],"answerId":"C","hint":"After **having**, choose the **past participle** for an earlier completed action.","explanation":"**Having measured** marks the activity as completed before the break.","keywords":["perfect-participle"],"skill":"perfect-participle","contextKey":"participle-clauses-3","fingerprint":"b7140758b469a2161b25073fd174f0b34dbb16ac52618b6f18e035f87cd12c3e","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-participles"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["After **having**, choose the **past participle** for an earlier completed action.","**Having measured** marks the activity as completed before the break.","Choose **measured**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A to-infinitive does not follow having in a perfect participle clause.","B":"This would foreground earlier ongoing activity rather than the requested completed simple-perfect action.","C":"**Having measured** marks the activity as completed before the break.","D":"Having requires a past participle for this perfect clause."}}},{"id":"b3d500b9